const raw = $input.first().json;
const cutoff7d = Date.now() - 7 * 24 * 60 * 60 * 1000;
const allOrders = Array.isArray(raw) ? raw : [];
const orders = allOrders.filter(o => new Date(o.created_at).getTime() > cutoff7d);
const count = orders.length;
const total = orders.reduce((s, o) => s + (o.total || 0), 0);
const avg = count > 0 ? total / count : 0;
const rows = orders.map(o => {
  const ph = o.users || {};
  const date = new Date(o.created_at).toLocaleDateString('fr-FR');
  return `<tr><td style='padding:8px;border:1px solid #ddd'>${o.id.slice(0,8).toUpperCase()}</td><td style='padding:8px;border:1px solid #ddd'>${date}</td><td style='padding:8px;border:1px solid #ddd'>${ph.name || '?'}</td><td style='padding:8px;border:1px solid #ddd'>${(o.total||0).toFixed(2)} MAD</td></tr>`;
}).join('');
const week = new Date().toLocaleDateString('fr-FR', {year:'numeric', month:'long', day:'numeric'});
let html = `<div style='font-family:Arial,sans-serif;max-width:600px;margin:0 auto'><div style='background:#1a472a;color:white;padding:20px;text-align:center'><h1>Rapport Hebdomadaire Neoval Pharma</h1><p>Semaine du ${week}</p></div><div style='padding:20px'><h2>Resume</h2><table style='width:100%'><tr><td style='padding:8px'><strong>Commandes livrees</strong></td><td style='padding:8px'>${count}</td></tr><tr><td style='padding:8px'><strong>Chiffre d affaires</strong></td><td style='padding:8px'>${total.toFixed(2)} MAD</td></tr><tr><td style='padding:8px'><strong>Panier moyen</strong></td><td style='padding:8px'>${avg.toFixed(2)} MAD</td></tr></table></div>`;
if (count > 0) {
  html += `<div style='padding:20px'><h2>Detail</h2><table style='width:100%;border-collapse:collapse'><thead><tr style='background:#f5f5f5'><th style='padding:8px;text-align:left;border:1px solid #ddd'>Ref</th><th style='padding:8px;border:1px solid #ddd'>Date</th><th style='padding:8px;border:1px solid #ddd'>Pharmacie</th><th style='padding:8px;border:1px solid #ddd'>Total</th></tr></thead><tbody>${rows}</tbody></table></div>`;
} else {
  html += '<p style="padding:20px">Aucune commande livree cette semaine.</p>';
}
html += '</div>';
return [{ json: { html, subject: '[Neoval] Rapport semaine - ' + count + ' commandes - ' + total.toFixed(2) + ' MAD' } }];

const allOrders = $('Commandes 30 derniers jours').first().json;
const pharmacies = $input.first().json;
const cutoff30d = Date.now() - 30 * 24 * 60 * 60 * 1000;
const activeIds = new Set(
  (Array.isArray(allOrders) ? allOrders : [])
    .filter(o => new Date(o.created_at).getTime() > cutoff30d)
    .map(o => o.placed_by)
);
const inactive = (Array.isArray(pharmacies) ? pharmacies : []).filter(p => !activeIds.has(p.id));
if (inactive.length === 0) return [];
return inactive.map(p => ({
  json: {
    email: p.email,
    name: p.name || p.email,
    subject: 'Votre espace Neoval Pharma vous attend',
    html: `<div style='font-family:Arial,sans-serif;max-width:600px;margin:0 auto'><div style='background:#1a472a;color:white;padding:20px;text-align:center'><h1>Bonjour ${p.name || 'cher partenaire'},</h1></div><div style='padding:20px'><p>Nous n avons pas recu de commande de votre pharmacie depuis plus de 30 jours.</p><p>Notre catalogue est enrichi. N hesitez pas a consulter nos dernieres nouveautes.</p><p><a href='https://tyk9807.github.io/neoval-portal/Catalogue.html' style='background:#1a472a;color:white;padding:12px 24px;text-decoration:none;border-radius:4px;display:inline-block;margin-top:10px'>Voir le catalogue</a></p></div></div>`
  }
}));
